"string",\n      "pattern": "^causal_relation_object:[0-9a-f]{64}\$"\n    },\n    "occId": {\n      "type": "string",\n      "pattern": "^occurrent:[0-9a-f]{64}\$"\n    },\n    "temporalWindow": {\n      "type": "object",\n      "required": [\n        "minimum_delay",\n        "maximum_delay",\n        "unit"\n      ],\n      "additionalProperties": false,\n      "properties": {\n        "minimum_delay": {\n          "type": "number",\n          "minimum": 0\n        },\n        "maximum_delay": {\n          "type": "number",\n          "minimum": 0\n        },\n        "unit": {\n          "enum": [\n            "instant",\n            "seconds",\n            "minutes",\n            "hours",\n            "days",\n            "weeks",\n            "months",\n            "years",\n            "ticks"\n          ],\n          "description": "3.0.0: the wall-clock units carry a fixed seconds mapping; \'ticks\' is a discrete, dimensionless ORDINAL unit (a step counter) with NO wall-clock mapping - a tick window is ordered by integer comparison, and a tick window and a wall-clock window are different dimensions that do not compare."\n        }\n      }\n    }\n  }\n}\n',
