  'cross_stratal_seam.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/cross_stratal_seam.schema.json",\n  "title": "Cross Stratal Seam",\n  "description": "3.0.0. A first-class MANAGED record of a legitimate jump across NON-ADJACENT strata. Where the Causal Relation Object\'s boolean \'skips\' flag can only assert THAT a relation crosses non-adjacent strata, a Cross Stratal Seam records HOW HONEST that jump is: its mechanism_status distinguishes \'a mechanism exists but is deliberately unmodeled here\' from \'no mechanism exists\', and an optional chain draws the intervening adjacent-stratum pathway. Its HOME is the coarsest stratum it touches (the endpoint of greater ordinal), which a layer-to-stratum binding can check. The \'skips\' boolean is SUBORDINATED to this construct: a bare skipping Causal Relation Object remains valid and is the coarse, mechanism-status-unspecified form.",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "source",\n    "target",\n    "mechanism_status"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^cross_stratal_seam:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "cross_stratal_seam"\n    },\n    "source": {\n      "type": "string",\n      "pattern": "^occurrent:[0-9a-f]{64}\$",\n      "description": "one endpoint occurrent of the seam; its stratum ordinal is one end of the jump"\n    },\n    "target": {\n      "type": "string",\n      "pattern": "^occurrent:[0-9a-f]{64}\$",\n      "description": "the other endpoint occurrent of the seam; its stratum ordinal is the other end of the jump"\n    },\n    "mechanism_status": {\n      "enum": [\n        "unmodeled",\n        "absent"\n      ],\n      "description": "the HONEST-IGNORANCE distinction. \'unmodeled\': an intervening mechanism EXISTS across the skipped strata but is deliberately not drawn here. \'absent\': there is genuinely NO intervening mechanism - the jump is direct. This is exactly what the boolean skips flag could not say."\n    },\n    "chain": {\n      "type": "array",\n      "minItems": 1,\n      "items": {\n        "type": "string",\n        "pattern": "^occurrent:[0-9a-f]{64}\$"\n      },\n      "description": "OPTIONAL. The intervening pathway DRAWN as an ordered list of occurrents at INTERVENING strata (each strictly between the two endpoints\' stratum ordinals, same scheme, strictly monotone from one endpoint toward the other). When present the seam is DRAWN, so its mechanism_status must be \'unmodeled\', never \'absent\' (a drawn mechanism is not absent)."\n    }\n  }\n}\n',
  'enrichment.schema.json':
