  'occurrent.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/occurrent.schema.json",\n  "title": "Occurrent",\n  "type": "object",\n  "required": [\n    "id",\n    "label",\n    "category"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^occurrent:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "occurrent"\n    },\n    "label": {\n      "type": "string",\n      "minLength": 1,\n      "pattern": "^[a-z][a-z0-9_]*\$",\n      "description": "canonical label: English, lowercase snake_case, whole words (press_button, light_on); homonyms disambiguated by qualification (charge_battery, charge_attack)"\n    },\n    "category": {\n      "enum": [\n        "action",\n        "event",\n        "process",\n        "state",\n        "state_change"\n      ],\n      "description": "REQUIRED and CLOSED so identity inputs are deterministic; extending this enumeration is a MAJOR version change (GOVERNANCE.md)"\n    },\n    "stratum": {\n      "type": "string",\n      "pattern": "^stratum:[0-9a-f]{64}\$",\n      "description": "OPTIONAL, IDENTITY-BEARING: the level of description at which this occurrent is pitched (2.0.0 N3.3)"\n    }\n  }\n}\n',
