  'predicted_occurrence.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/predicted_occurrence.schema.json",\n  "title": "Predicted Occurrence",\n  "description": "4.0.0. A first-class record of an EXPECTATION: an occurrent type predicted, by a stated predictor, to occur over a stated window. A prediction is NOT an assertion that the thing happened - it is the sibling of the token_occurrence that has not (yet) happened, and it satisfies no rule that requires a token_occurrence (Rule 24). Its interval MUST carry exactly ONE temporal dimension: a wall-clock start (with optional end) or an ordinal start_tick (with optional end_tick), never both and never neither. The optional strength is the predicted probability - part of the PREDICTED CONTENT itself, identity-bearing when present, not a provenance evaluation (the narrow, deliberate 4.0.0 extension of Principle P4).",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "instantiates",\n    "interval",\n    "predictor"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^predicted_occurrence:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "predicted_occurrence"\n    },\n    "instantiates": {\n      "type": "string",\n      "pattern": "^occurrent:[0-9a-f]{64}\$",\n      "description": "the occurrent TYPE predicted to occur; MANDATORY (P1)"\n    },\n    "interval": {\n      "\$ref": "#/\$defs/predicted_interval"\n    },\n    "predictor": {\n      "type": "string",\n      "pattern": "^(continuant|token_individual):[0-9a-f]{64}\$",\n      "description": "the predicting source - a MODELED agent or construct inside the ontology (a continuant type or a particular token individual), never a cryptographic key"\n    },\n    "strength": {\n      "type": "number",\n      "description": "OPTIONAL, identity-bearing when present: the predicted probability, part of the predicted content itself, NOT a provenance evaluation (4.0.0 Locked Decision extension of Principle P4)"\n    }\n  },\n  "\$defs": {\n    "predicted_interval": {\n      "type": "object",\n      "additionalProperties": false,\n      "properties": {\n        "start": {\n          "type": "string",\n          "format": "date-time",\n          "description": "RFC 3339, UTC, mandatory Z suffix - the wall-clock dimension"\n        },\n        "end": {\n          "type": "string",\n          "format": "date-time"\n        },\n        "start_tick": {\n          "type": "integer",\n          "minimum": 0,\n          "description": "the ordinal dimension: a discrete tick with NO wall-clock mapping (Rule 23)"\n        },\n        "end_tick": {\n          "type": "integer",\n          "minimum": 0\n        }\n      },\n      "description": "the predicted window. Rule 24 enforces exactly ONE temporal dimension: start (wall-clock, optional end) or start_tick (ordinal, optional end_tick), never both (dimension_conflict, HARD) and never neither (missing_dimension, HARD)"\n    }\n  }\n}\n',
  'prediction_error.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/prediction_error.schema.json",\n  "title": "Prediction Error",\n  "description": "4.0.0. The first-class record of how a prediction met the world: the graded discrepancy between a predicted_occurrence and what was - or was not - observed. When observed is present it names the token_occurrence that answered the prediction and MUST instantiate the same occurrent the prediction instantiates (Rule 24, pairing_mismatch, HARD); when observed is ABSENT the predicted occurrence was not fulfilled by any recorded occurrence. discrepancy reads actual minus expected: positive = exceeded expectation, negative = fell short, zero = fulfilled.",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "predicted",\n    "discrepancy"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^prediction_error:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "prediction_error"\n    },\n    "predicted": {\n      "type": "string",\n      "pattern": "^predicted_occurrence:[0-9a-f]{64}\$",\n      "description": "the prediction this error grades; MANDATORY - an error without a prediction is not an error"\n    },\n    "observed": {\n      "type": "string",\n      "pattern": "^token_occurrence:[0-9a-f]{64}\$",\n      "description": "OPTIONAL: the token occurrence that answered the prediction. ABSENT means the predicted occurrence was not fulfilled by any recorded occurrence - the surprise of nothing arriving"\n    },\n    "discrepancy": {\n      "type": "number",\n      "description": "signed, graded; actual minus expected - positive = exceeded expectation, negative = fell short, zero = fulfilled (the comparator sign convention)"\n    }\n  }\n}\n',
  'quality.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/quality.schema.json",\n  "title": "Quality",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "label",\n    "datatype"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^quality:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "quality"\n    },\n    "label": {\n      "type": "string",\n      "minLength": 1,\n      "pattern": "^[a-z][a-z0-9_]*\$",\n      "description": "for example: cortisol_concentration, membrane_potential, mass"\n    },\n    "datatype": {\n      "enum": [\n        "quantity",\n        "categorical",\n        "boolean"\n      ]\n    },\n    "unit": {\n      "type": "string",\n      "description": "the canonical UCUM unit code; REQUIRED when datatype is quantity, and MUST be absent otherwise"\n    },\n    "stratum": {\n      "type": "string",\n      "pattern": "^stratum:[0-9a-f]{64}\$",\n      "description": "optional: the level of description at which this quality is defined"\n    }\n  }\n}\n',
  'realizable.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/realizable.schema.json",\n  "title": "Realizable Entity",\n  "type": "object",\n  "required": [\n    "id",\n    "kind",\n    "bearer"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^realizable:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "realizable"\n    },\n    "kind": {\n      "enum": [\n        "disposition",\n        "function",\n        "role"\n      ]\n    },\n    "bearer": {\n      "type": "string",\n      "pattern": "^continuant:[0-9a-f]{64}\$"\n    },\n    "label": {\n      "type": "string",\n      "minLength": 1,\n      "pattern": "^[a-z][a-z0-9_]*\$",\n      "description": "OPTIONAL, IDENTITY-BEARING: the name of this disposition, function, or role. Repairs the 1.0.0 identity collision that limited a bearer to one realizable per kind (2.0.0 4.3)"\n    }\n  }\n}\n',
  'retraction.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/retraction.schema.json",\n  "title": "Retraction",\n  "type": "object",\n  "required": [\n    "id",\n    "retracts",\n    "source",\n    "timestamp"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^retraction:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "retraction"\n    },\n    "retracts": {\n      "type": "string",\n      "pattern": "^(assertion|enrichment):[0-9a-f]{64}\$",\n      "description": "the assertion or enrichment being withdrawn"\n    },\n    "source": {\n      "type": "string",\n      "pattern": "^ed25519:[0-9a-f]{64}\$",\n      "description": "must be the retracted record\'s source, or a key in its succession lineage"\n    },\n    "reason": {\n      "type": "string"\n    },\n    "timestamp": {\n      "type": "string",\n      "format": "date-time"\n    },\n    "signature": {\n      "type": "string",\n      "pattern": "^[0-9a-f]{128}\$"\n    }\n  }\n}\n',
  'state.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/state.schema.json",\n  "title": "State Assertion",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "subject",\n    "quality",\n    "value",\n    "interval"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^state_assertion:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "state_assertion"\n    },\n    "subject": {\n      "type": "string",\n      "pattern": "^token_individual:[0-9a-f]{64}\$",\n      "description": "the PARTICULAR individual in this state"\n    },\n    "quality": {\n      "type": "string",\n      "pattern": "^quality:[0-9a-f]{64}\$"\n    },\n    "value": {\n      "\$ref": "#/\$defs/value"\n    },\n    "interval": {\n      "\$ref": "https://causalontology.org/schema/token.schema.json#/\$defs/interval",\n      "description": "over what span of absolute time the subject held this value"\n    }\n  },\n  "\$defs": {\n    "value": {\n      "oneOf": [\n        {\n          "type": "object",\n          "required": [\n            "quantity",\n            "unit"\n          ],\n          "additionalProperties": false,\n          "properties": {\n            "quantity": {\n              "type": "number"\n            },\n            "unit": {\n              "type": "string",\n              "minLength": 1,\n              "description": "UCUM unit code; MUST match the quality\'s unit"\n            }\n          }\n        },\n        {\n          "type": "object",\n          "required": [\n            "categorical"\n          ],\n          "additionalProperties": false,\n          "properties": {\n            "categorical": {\n              "type": "string",\n              "minLength": 1\n            }\n          }\n        },\n        {\n          "type": "object",\n          "required": [\n            "boolean"\n          ],\n          "additionalProperties": false,\n          "properties": {\n            "boolean": {\n              "type": "boolean"\n            }\n          }\n        }\n      ]\n    }\n  }\n}\n',
  'stratum.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/stratum.schema.json",\n  "title": "Stratum",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "label",\n    "scheme",\n    "ordinal"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^stratum:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "stratum"\n    },\n    "label": {\n      "type": "string",\n      "minLength": 1,\n      "pattern": "^[a-z][a-z0-9_]*\$",\n      "description": "canonical label, snake_case, English (for example: cellular, macromolecular)"\n    },\n    "scheme": {\n      "type": "string",\n      "minLength": 1,\n      "pattern": "^[a-z][a-z0-9_]*\$",\n      "description": "the stratification scheme this stratum belongs to; strata are comparable only within a scheme"\n    },\n    "ordinal": {\n      "type": "integer",\n      "description": "position within the scheme; STRICTLY LOWER IS FINER-GRAINED; need not be contiguous"\n    },\n    "unit": {\n      "type": "string",\n      "pattern": "^[a-z][a-z0-9_]*\$",\n      "description": "the principal unit of analysis at this stratum (for example: cell, synapse, region)"\n    },\n    "governs": {\n      "type": "array",\n      "items": {\n        "type": "string",\n        "pattern": "^[a-z][a-z0-9_]*\$"\n      },\n      "description": "the governing frameworks or bodies of law at this stratum (for example: quantum_mechanics, cell_biology)"\n    }\n  }\n}\n',
  'succession.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/succession.schema.json",\n  "title": "Succession",\n  "type": "object",\n  "required": [\n    "id",\n    "predecessor",\n    "successor",\n    "timestamp"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^succession:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "succession"\n    },\n    "predecessor": {\n      "type": "string",\n      "pattern": "^ed25519:[0-9a-f]{64}\$"\n    },\n    "successor": {\n      "type": "string",\n      "pattern": "^ed25519:[0-9a-f]{64}\$"\n    },\n    "timestamp": {\n      "type": "string",\n      "format": "date-time"\n    },\n    "signature": {\n      "type": "string",\n      "pattern": "^[0-9a-f]{128}\$",\n      "description": "signed by the PREDECESSOR key"\n    }\n  }\n}\n',
  'token.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/token.schema.json",\n  "title": "Token Occurrence",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "instantiates",\n    "interval"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^token_occurrence:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "token_occurrence"\n    },\n    "instantiates": {\n      "type": "string",\n      "pattern": "^occurrent:[0-9a-f]{64}\$",\n      "description": "the occurrent TYPE of which this is an instance; MANDATORY (P1)"\n    },\n    "interval": {\n      "\$ref": "#/\$defs/interval"\n    },\n    "participants": {\n      "type": "array",\n      "items": {\n        "\$ref": "#/\$defs/rolefill"\n      }\n    },\n    "locus": {\n      "type": "string",\n      "pattern": "^token_individual:[0-9a-f]{64}\$",\n      "description": "optional: the particular place or bearer at which it occurred"\n    },\n    "observer": {\n      "type": "string",\n      "pattern": "^ed25519:[0-9a-f]{64}\$",\n      "description": "optional: the source whose experience this token belongs to"\n    }\n  },\n  "\$defs": {\n    "interval": {\n      "type": "object",\n      "required": [\n        "start"\n      ],\n      "additionalProperties": false,\n      "properties": {\n        "start": {\n          "type": "string",\n          "format": "date-time",\n          "description": "RFC 3339, UTC, mandatory Z suffix"\n        },\n        "end": {\n          "type": "string",\n          "format": "date-time"\n        },\n        "open": {\n          "type": "boolean",\n          "description": "true asserts the occurrence had NOT ENDED as of this record"\n        }\n      }\n    },\n    "rolefill": {\n      "type": "object",\n      "required": [\n        "role",\n        "filler"\n      ],\n      "additionalProperties": false,\n      "properties": {\n        "role": {\n          "enum": [\n            "agent",\n            "patient",\n            "instrument",\n            "recipient",\n            "source",\n            "destination",\n            "medium"\n          ],\n          "description": "CLOSED enumeration; extending it is a MAJOR change"\n        },\n        "filler": {\n          "type": "string",\n          "pattern": "^token_individual:[0-9a-f]{64}\$"\n        }\n      }\n    }\n  }\n}\n',
  'token_causal_claim.schema.json':
      '{\n  "\$schema": "https://json-schema.org/draft/2020-12/schema",\n  "\$id": "https://causalontology.org/schema/token_causal_claim.schema.json",\n  "title": "Token Causal Claim",\n  "type": "object",\n  "required": [\n    "id",\n    "type",\n    "causes",\n    "effects"\n  ],\n  "additionalProperties": false,\n  "properties": {\n    "id": {\n      "type": "string",\n      "pattern": "^token_causal_claim:[0-9a-f]{64}\$"\n    },\n    "type": {\n      "const": "token_causal_claim"\n    },\n    "causes": {\n      "type": "array",\n      "minItems": 1,\n      "items": {\n        "type": "string",\n        "pattern": "^token_occurrence:[0-9a-f]{64}\$"\n      }\n    },\n    "effects": {\n      "type": "array",\n      "minItems": 1,\n      "items": {\n        "type": "string",\n        "pattern": "^token_occurrence:[0-9a-f]{64}\$"\n      }\n    },\n    "covering_law": {\n      "type": "string",\n      "pattern": "^causal_relation_object:[0-9a-f]{64}\$",\n      "description": "OPTIONAL. The type-level Causal Relation Object this token claim instantiates."\n    },\n    "actual_delay": {\n      "type": "object",\n      "required": [\n        "duration",\n        "unit"\n      ],\n      "additionalProperties": false,\n      "properties": {\n        "duration": {\n          "type": "number",\n          "minimum": 0\n        },\n        "unit": {\n          "enum": [\n            "instant",\n            "seconds",\n            "minutes",\n            "hours",\n            "days",\n            "weeks",\n            "months",\n            "years",\n            "ticks"\n          ],\n          "description": "3.0.0: \'ticks\' is a discrete, dimensionless ORDINAL unit; a tick-unit observed delay compares to a tick-unit covering-law window by integer, and never to a wall-clock window."\n        }\n      },\n      "description": "the delay ACTUALLY OBSERVED on this occasion"\n    },\n    "counterfactual": {\n      "type": "boolean",\n      "description": "true asserts the BUT-FOR test for THIS OCCASION ONLY"\n    }\n  }\n}\n',
};
